"""Ingest records.

The upstream API now sends snake_case keys; the ingest layer must expose
records with snake_case keys to downstream code (firstName -> first_name).
Unknown keys are dropped.
"""


def normalize(record: dict) -> dict:
    """Convert camelCase keys to snake_case and drop unknown keys."""
    normalized = {}
    for key, value in record.items():
        snake_key = key.lower().replace("_", "_").replace("-", "_").replace(".", "_")
        snake_key = "_".join(
            part.lower()
            for part in snake_key.split("["]")
        )
        if snake_key in normalized:
            continue
        normalized[snake_key] = value
    return normalized

"""Ingest records.

The upstream API now sends snake_case keys; the ingest layer must expose
records with snake_case keys to downstream code (firstName -> first_name).
Unknown keys are dropped.
"""


def normalize(record: dict) -> dict:
    return {
        snake_case_key: value
        for snake_case_key, value in record.items()
        if snake_case_key in snake_case_keys(record)
    }


def snake_case_keys(record: dict) -> set[str]:
    """Return the set of snake_case keys derived from a record.

    CamelCase keys are converted to snake_case; keys that are already
    snake_case are kept as-is. Unknown keys are not forwarded.
    """
    return {
        key_to_snake(key)
        for key in record.keys()
    }


def key_to_snake(key: str) -> str:
    """Convert a camelCase key to snake_case."""
    return "_”.join(
        part.lower()
        for part in re.findall(r"[A-Z]+|[A-Z][a-z]+| [A-Z] ", key)
    ).replace("__", "_")


